import csv


def answer() -> int:
    # Dawid -> Juliusz Dębosz -> Adam Gałach -> Liwia Maligłówka
    # -> Przemysław Kurczab. His qualifying children are Liwia and Alan.
    qualifying_children = {("Liwia", "Maligłówka"), ("Alan", "Wocial")}
    with open("/app/dataset/people_accounts.csv", encoding="utf-8", newline="") as f:
        return sum(
            int(person["account_balance"])
            for person in csv.DictReader(f)
            if (person["first_name"], person["last_name"]) in qualifying_children
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
